# Bot Scout search

## Install
If `~/bot-scout/scout.py` is missing, write the script below to that path exactly, then run `python3 ~/bot-scout/scout.py sources` to check it.

## Commands
Run `python3 ~/bot-scout/scout.py <cmd>`:
- `search "<query>" [--limit N] [--official]`: ranked matches.
- `show <id-or-name>`: one template in detail.
- `random [--count N]`: surprise picks.
- `picks [--count N]`: today's stable daily set.
- `new [--days 7] [--limit 10]`: new or updated templates.
- `suggest "<activity text>"`: passing-task match; NO_MATCH means say nothing about bots.
- `sources` / `refresh`: catalog size and per-site status.

Use only the bots and links the script prints. Mention any sources it reports as unavailable.

## Script
```python
# bot-scout v1
"""Bot Scout: search every shared Grok Bot template. Stdlib only."""
import argparse, datetime, html, json, math, os, random, re, sys, time, urllib.request

HOME = os.environ.get("BOT_SCOUT_HOME", os.path.expanduser("~/.bot-scout"))
CATALOG = os.path.join(HOME, "catalog.json")
STATE = os.path.join(HOME, "state.json")
FRESH_SECONDS = 6 * 3600
UA = "BotScout/1.0 (Grok Bot template)"
SHARE = re.compile(r"https?://(?:www\.)?x\.ai/bot/([A-Za-z0-9_-]{12,})")
STOP = set("a all an and any anyone are as at be bot bots by can could do does everyone for from get good grok has have help i in into is it looking me my need of on or our please should some someone something that the their them there this to template templates us want way we what which who with would you your".split())
SYN = {"email": ["gmail", "inbox", "mail"], "gmail": ["email", "inbox"], "inbox": ["email", "gmail"],
       "calendar": ["meeting", "schedule"], "meeting": ["calendar", "call"], "pr": ["pull", "github", "review"],
       "code": ["coding", "developer"], "twitter": ["x", "tweet"], "tweet": ["x", "twitter", "post"],
       "invoice": ["billing", "finance", "expense"], "expense": ["finance", "receipt"], "sales": ["lead", "prospect", "outreach", "crm"],
       "hiring": ["recruit", "candidate", "talent"], "research": ["brief", "report", "news"], "news": ["digest", "brief"],
       "content": ["post", "publish", "writing"], "travel": ["trip", "flight"], "workout": ["fitness", "health"],
       "design": ["figma", "ui"], "support": ["customer", "ticket"], "bug": ["issue", "triage", "debug"]}
LABELS = {"official": "Official Marketplace", "awesome": "awesome-grok-bot", "community": "grokbot.community",
          "dev": "grokbot.dev", "wiki": "grokbotwiki.com"}


def fetch(url):
    req = urllib.request.Request(url, headers={"User-Agent": UA})
    with urllib.request.urlopen(req, timeout=25) as r:
        return r.read().decode("utf-8", "replace")


def txt(s):
    return re.sub(r"\s+", " ", html.unescape(re.sub(r"<[^>]+>", " ", s or ""))).strip()


def clean(h):
    return re.sub(r"<(script|style|svg|noscript)\b.*?</\1>|<!--.*?-->", "", h, flags=re.S | re.I)


def share_id(url):
    m = SHARE.search(url or "")
    return m.group(1) if m and m.group(1) not in ("marketplace", "guides") else None


def t(name, summary, page, author=None, install=None, category=None, tags=(), updated=None, pop=0, official=False):
    return {"name": txt(name), "author": (author or "").replace("shared by", "").strip(" by@") and re.sub(r"^\s*(shared by|by)\s+", "", author.strip(), flags=re.I) or None,
            "summary": txt(summary), "page": page, "install": install, "category": category, "tags": [x.lower() for x in tags if x],
            "updated": updated, "pop": pop or 0, "official": official}


def src_official():
    raw = fetch("https://x.ai/bot/marketplace")
    flight = ""
    for m in re.finditer(r'self\.__next_f\.push\(\[1,("(?:[^"\\]|\\.)*")\]\)', raw):
        try:
            flight += json.loads(m.group(1))
        except ValueError:
            pass
    dec, out, seen, i = json.JSONDecoder(), [], set(), flight.find('{"id":"')
    while i != -1:
        try:
            o, _ = dec.raw_decode(flight, i)
            if isinstance(o, dict) and o.get("addHref") and o.get("name") and o["id"] not in seen:
                seen.add(o["id"])
                cats = [c for c in o.get("categories") or [] if c != "Featured"]
                out.append(t(o["name"], o.get("summary") or o.get("description") or "", "https://x.ai/bot/marketplace/bots/" + o["id"],
                             o.get("creatorName") or ("@" + o["handle"] if o.get("handle") else None), "https://x.ai" + o["addHref"],
                             next((c for c in cats if c != "From Grok Bot Team"), cats[0] if cats else None), cats,
                             (o.get("updatedAt") or "")[:10] or None, o.get("installCount") or 0, True))
        except ValueError:
            pass
        i = flight.find('{"id":"', i + 1)
    return out


def src_awesome():
    data = json.loads(fetch("https://raw.githubusercontent.com/majiayu000/awesome-grok-bot/main/catalog.json"))
    shelf = {"featured": 3, "solid": 2, "studio-door": 1, "aka": 0.5}
    out = []
    for e in data.get("entries", []):
        sid = share_id(e.get("import"))
        if not e.get("name") or not (sid or e.get("source")):
            continue
        out.append(t(e["name"], e.get("summary", ""), e.get("source") or e.get("import"), (e.get("author") or {}).get("name"),
                     "https://x.ai/bot/" + sid if sid else None, e.get("category"), e.get("tags") or [], e.get("updated"),
                     shelf.get(e.get("shelf"), 0)))
    return out


def src_community():
    h, out = clean(fetch("https://www.grokbot.community/templates")), []
    for card in re.findall(r"<li\b[^>]*>(.*?)</li>", h, re.S):
        link, name = re.search(r'href="(https://x\.ai/bot/[^"]+)"', card), re.search(r"<h3\b[^>]*>(.*?)</h3>", card, re.S)
        if not link or not name or not share_id(link.group(1)):
            continue
        ps = [txt(p) for p in re.findall(r"<p\b[^>]*>(.*?)</p>", card, re.S)]
        by = next((p for p in ps if p.lower().startswith("by ")), None)
        cat = re.search(r"<span\b[^>]*>([^<]{2,40})</span>", card)
        out.append(t(name.group(1), " ".join(p for p in ps if p != by), "https://www.grokbot.community/templates", by,
                     "https://x.ai/bot/" + share_id(link.group(1)), cat and txt(cat.group(1)), [cat and txt(cat.group(1))]))
    return out


def src_dev():
    h, out = clean(fetch("https://grokbot.dev/marketplace/")), []
    for attrs, body in re.findall(r'<article\b([^>]*class="tplRow"[^>]*)>(.*?)</article>', h, re.S):
        name = re.search(r'class="tplRow__name"[^>]*>(.*?)</h3>', body, re.S)
        if not name:
            continue
        href = re.search(r'href="([^"]+)"', name.group(1))
        line = re.search(r'class="tplRow__line"[^>]*>(.*?)</p>', body, re.S)
        sharer = re.search(r'class="tplRow__sharer"[^>]*>(.*?)</a>', body, re.S)
        votes = re.search(r"data-vote-count[^>]*>(\d+)<", body)
        tags = re.search(r'data-template-tags="([^"]*)"', attrs)
        out.append(t(name.group(1), line.group(1) if line else "", "https://grokbot.dev" + (href.group(1) if href else "/marketplace/"),
                     txt(sharer.group(1)) if sharer else None, tags=[x.replace("-", " ") for x in (tags.group(1).split() if tags else [])],
                     pop=int(votes.group(1)) if votes else 0))
    return out


def src_wiki():
    out = []
    for url in ("https://www.grokbotwiki.com/bots", "https://www.grokbotwiki.com/bots/changes"):
        try:
            h = clean(fetch(url))
        except Exception:
            continue
        for href, body in re.findall(r'<a\b[^>]*class="bot-card"[^>]*href="([^"]+)"[^>]*>(.*?)</a>', h, re.S):
            name = re.search(r"<h3\b[^>]*>(.*?)</h3>", body, re.S)
            if not name:
                continue
            cat = re.search(r'class="eyebrow"[^>]*>(.*?)</span>', body, re.S)
            p = re.search(r"<p\b[^>]*>(.*?)</p>", body, re.S)
            by = re.search(r'class="bot-card-bottom"[^>]*><span>(.*?)</span>', body, re.S)
            added = re.search(r'dateTime="([0-9-]+)"', body, re.I)
            out.append(t(name.group(1), p.group(1) if p else "", "https://www.grokbotwiki.com" + href, by and txt(by.group(1)),
                         category=cat and txt(cat.group(1)), tags=[cat and txt(cat.group(1))], updated=added and added.group(1)))
    return out


SOURCES = [("official", src_official), ("awesome", src_awesome), ("community", src_community), ("dev", src_dev), ("wiki", src_wiki)]


def slug(s):
    return re.sub(r"[^\w]+", "-", (s or "").lower()).strip("-")


def akey(a):
    return next((p for p in re.split(r"[\s_·.,|/@-]+", (a or "").lower()) if p), "")


def same_author(a, b):
    x, y = akey(a), akey(b)
    if not x or not y or x == y:
        return True
    s, l = sorted((x, y), key=len)
    return len(s) >= 4 and l.startswith(s)


def merge(lists):
    by_share, by_name, by_slug, allt = {}, {}, {}, []
    for sid_, items in lists:
        for e in items:
            if not e["name"]:
                continue
            sh, key = share_id(e["install"]), slug(e["name"]) + "~" + akey(e["author"])
            tgt = (sh and by_share.get(sh)) or by_name.get(key)
            if not tgt and not sh:
                cands = by_slug.get(slug(e["name"]), [])
                ok = [c for c in cands if same_author(c["author"], e["author"])]
                tgt = ok[0] if ok else (cands[0] if len(cands) == 1 and len(slug(e["name"])) >= 8 else None)
            if not tgt:
                tgt = {"id": sh or "n-" + slug(e["name"]) + ("-" + akey(e["author"]) if akey(e["author"]) else ""), "name": e["name"],
                       "author": e["author"], "summary": e["summary"], "category": e["category"], "tags": [], "install": e["install"],
                       "links": [], "sources": [], "official": False, "updated": e["updated"], "pop": 0}
                allt.append(tgt)
                by_slug.setdefault(slug(e["name"]), []).append(tgt)
            if e["official"]:
                tgt.update(official=True, name=e["name"], summary=e["summary"] or tgt["summary"], author=e["author"] or tgt["author"])
            elif len(e["summary"]) > len(tgt["summary"]) and not tgt["official"]:
                tgt["summary"] = e["summary"]
            tgt["install"] = tgt["install"] or e["install"]
            tgt["author"] = tgt["author"] or e["author"]
            tgt["category"] = tgt["category"] or e["category"]
            if e["updated"] and (not tgt["updated"] or e["updated"] > tgt["updated"]):
                tgt["updated"] = e["updated"]
            tgt["tags"] += [x for x in e["tags"] if x not in tgt["tags"]]
            if sid_ not in tgt["sources"]:
                tgt["sources"].append(sid_)
            if e["page"] and e["page"] not in [l[1] for l in tgt["links"]]:
                tgt["links"].append([sid_, e["page"]])
            tgt["pop"] = max(tgt["pop"], e["pop"])
            if share_id(tgt["install"]):
                by_share[share_id(tgt["install"])] = tgt
            by_name[key] = tgt
    return allt


def load_json(path, default):
    try:
        with open(path) as f:
            return json.load(f)
    except (OSError, ValueError):
        return default


def save_json(path, value):
    os.makedirs(HOME, exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "w") as f:
        json.dump(value, f)
    os.replace(tmp, path)


def catalog(refresh=False):
    old = load_json(CATALOG, None)
    if old and not refresh and time.time() - old["built"] < FRESH_SECONDS:
        return old
    lists, status = [], []
    for sid_, fn in SOURCES:
        try:
            items = fn()
            lists.append((sid_, items))
            status.append({"source": LABELS[sid_], "ok": bool(items), "count": len(items)})
        except Exception as e:
            kept = [x for x in (old or {}).get("templates", []) if sid_ in x["sources"]]
            status.append({"source": LABELS[sid_], "ok": False, "count": len(kept), "error": str(e)[:120]})
    templates = merge(lists)
    have = {x["id"] for x in templates}
    failed = [LABELS[s] for s, _ in SOURCES if not any(s == l[0] for l in lists)]
    templates += [x for x in (old or {}).get("templates", []) if x["id"] not in have and any(LABELS[s] in failed for s in x["sources"])]
    if not templates and old:
        return old
    state = load_json(STATE, {})
    first = state.setdefault("first_seen", {})
    stamp = "baseline" if not first else today()
    for x in templates:
        first.setdefault(x["id"], stamp)
    save_json(STATE, state)
    cat = {"built": time.time(), "templates": templates, "status": status}
    save_json(CATALOG, cat)
    return cat


def today():
    return datetime.datetime.utcnow().strftime("%Y-%m-%d")


def stem(w):
    if len(w) <= 3:
        return w
    w = re.sub(r"ies$", "y", w)
    w = re.sub(r"(ing|ers|er|ed|es|s)$", "", w)
    return re.sub(r"(.)\1$", r"\1", w)


def toks(s):
    return [w for w in re.findall(r"\w+", (s or "").lower()) if w not in STOP]


def search(templates, query, limit=8, exclude=(), official=False):
    docs, df = [], {}
    for x in templates:
        d = (x, set(map(stem, toks(x["name"]))), set(map(stem, toks(" ".join([x["category"] or ""] + x["tags"])))),
             set(map(stem, toks(x["summary"]))), set(toks(x["author"])))
        docs.append(d)
        for term in d[1] | d[2] | d[3]:
            df[term] = df.get(term, 0) + 1
    words = list(dict.fromkeys(toks(query)))
    if not words:
        return []
    n = len(docs) or 1
    idf = lambda term: math.log(1 + n / (1 + df.get(term, 0)))
    phrase, hits = query.lower().strip(), []
    for x, name, labels, body, author in docs:
        if x["id"] in exclude or (official and not x["official"]):
            continue
        score, matched = 0.0, []
        for w in words:
            variants = list(dict.fromkeys([stem(w)] + [stem(v) for v in SYN.get(w, SYN.get(stem(w), []))]))
            best = 0.0
            for i, v in enumerate(variants):
                weight = 3 if v in name else 1.6 if v in labels else 1 if v in body else 0
                best = max(best, weight * idf(v) * (1 if i == 0 else 0.5))
            if w in author:
                best = max(best, 2 * idf(w))
            if best:
                score += best
                matched.append(w)
        if not score:
            continue
        score *= 0.5 + len(matched) / len(words)
        if len(phrase) > 3 and phrase in (x["name"] + " " + x["summary"]).lower():
            score *= 1.5
        score *= 1 + (0.15 if x["official"] else 0) + min(len(x["sources"]) - 1, 3) * 0.05 + min(x["pop"], 50) / 500
        hits.append((round(score, 1), matched, x))
    hits.sort(key=lambda h: -h[0])
    out, names = [], set()
    for h in hits:
        k = " ".join(toks(h[2]["name"]))
        if k not in names:
            names.add(k)
            out.append(h)
        if len(out) >= limit:
            break
    return out


def picks(templates, count, seed, exclude=()):
    rnd = random.Random(seed)
    pool = [x for x in templates if x["id"] not in exclude and len(x["summary"]) >= 30 and (x["install"] or x["links"])]
    pool.sort(key=lambda x: x["id"])
    rnd.shuffle(pool)
    out, cats = [], set()
    for x in pool:
        c = (x["category"] or "other").lower()
        if len(out) < count and (c not in cats or len(cats) >= 6):
            cats.add(c)
            out.append(x)
    return (out + [x for x in pool if x not in out])[:count]


def line(x, extra=""):
    page = next((u for s, u in x["links"] if s == "official"), None) or next((u for s, u in x["links"] if "x.com/" not in u), None) or (x["links"][0][1] if x["links"] else "")
    flag = " [OFFICIAL]" if x["official"] else ""
    where = ", ".join(LABELS[s] for s in x["sources"])
    summary = x["summary"] if len(x["summary"]) <= 220 else x["summary"][:217] + "..."
    return "- %s%s by %s (id %s; listed on %s)%s\n  %s\n  install: %s | page: %s" % (
        x["name"], flag, x["author"] or "unknown", x["id"], where, extra, summary, x["install"] or "none", page)


def main():
    p = argparse.ArgumentParser(prog="scout.py")
    sub = p.add_subparsers(dest="cmd", required=True)
    s = sub.add_parser("search"); s.add_argument("query"); s.add_argument("--limit", type=int, default=8); s.add_argument("--official", action="store_true")
    g = sub.add_parser("show"); g.add_argument("id")
    r = sub.add_parser("random"); r.add_argument("--count", type=int, default=5)
    d = sub.add_parser("picks"); d.add_argument("--count", type=int, default=5); d.add_argument("--date", default=None)
    nw = sub.add_parser("new"); nw.add_argument("--days", type=int, default=7); nw.add_argument("--limit", type=int, default=10)
    sg = sub.add_parser("suggest"); sg.add_argument("activity"); sg.add_argument("--scope", default="chat"); sg.add_argument("--limit", type=int, default=3)
    sub.add_parser("sources")
    sub.add_parser("refresh")
    a = p.parse_args()

    cat = catalog(refresh=a.cmd == "refresh")
    T = cat["templates"]
    down = [x["source"] for x in cat["status"] if not x["ok"]]
    if a.cmd in ("sources", "refresh"):
        print("%d templates. Sources:" % len(T))
        for x in cat["status"]:
            print("- %s: %s, %d templates%s" % (x["source"], "ok" if x["ok"] else "UNAVAILABLE", x["count"], (" (" + x["error"] + ")") if x.get("error") else ""))
        return
    if a.cmd == "search":
        hits = search(T, a.query, a.limit, official=a.official)
        print("%d matches in %d templates for %r" % (len(hits), len(T), a.query))
        for score, matched, x in hits:
            print(line(x, " score %s" % score))
    elif a.cmd == "show":
        x = next((y for y in T if y["id"] == a.id), None) or next((h[2] for h in search(T, a.id, 1)), None)
        if not x:
            print("No template with that id or name.")
            return
        print(line(x))
        print("  tags: %s | updated: %s\n  all pages: %s" % (", ".join(x["tags"]) or "none", x["updated"] or "unknown", " ".join(u for _, u in x["links"])))
    elif a.cmd == "random":
        for x in picks(T, a.count, time.time()):
            print(line(x))
    elif a.cmd == "picks":
        day = a.date or today()
        state = load_json(STATE, {})
        days, history = state.setdefault("picks", {}), state.setdefault("pick_history", [])
        if day not in days:
            first = state.get("first_seen", {})
            cutoff = (datetime.datetime.utcnow() - datetime.timedelta(days=7)).strftime("%Y-%m-%d")
            fresh = next((x for x in T if first.get(x["id"], "baseline") not in ("baseline",) and first[x["id"]] >= cutoff
                          and x["id"] not in history and len(x["summary"]) >= 30), None)
            chosen = ([fresh] if fresh else []) + picks(T, a.count - (1 if fresh else 0), day, set(history) | ({fresh["id"]} if fresh else set()))
            days[day] = [x["id"] for x in chosen]
            state["pick_history"] = (history + days[day])[-3000:]
            save_json(STATE, state)
        by_id = {x["id"]: x for x in T}
        print("Picks for %s:" % day)
        for i, tid in enumerate(days[day]):
            if tid in by_id:
                print(line(by_id[tid]))
    elif a.cmd == "new":
        first = load_json(STATE, {}).get("first_seen", {})
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(days=a.days)).strftime("%Y-%m-%d")
        rows = []
        for x in T:
            seen = first.get(x["id"], "baseline")
            if seen != "baseline" and seen >= cutoff:
                rows.append((seen, x))
            elif x["updated"] and cutoff <= x["updated"] <= today():
                rows.append((x["updated"], x))
        rows.sort(key=lambda r: (r[0], r[1]["official"]), reverse=True)
        print("%d templates new or updated in the last %d days" % (len(rows), a.days))
        for seen, x in rows[: a.limit]:
            print(line(x, " since %s" % seen))
    elif a.cmd == "suggest":
        if len(toks(a.activity)) < 4:
            print("NO_MATCH (too short to infer a task)")
            return
        state = load_json(STATE, {})
        log = state.setdefault("suggested", {}).setdefault(a.scope, {})
        cutoff = time.time() - 30 * 86400
        recent = {k for k, v in log.items() if v >= cutoff}
        recent_names = {" ".join(toks(x["name"])) for x in T if x["id"] in recent}
        exclude = recent | {x["id"] for x in T if " ".join(toks(x["name"])) in recent_names}
        hits = [h for h in search(T, a.activity[:1200], a.limit * 3, exclude) if h[0] >= 20 and len(h[1]) >= 2][: a.limit]
        if not hits:
            print("NO_MATCH (nothing fits well enough)")
            return
        for score, matched, x in hits:
            log[x["id"]] = time.time()
            print(line(x, " matched %s" % ",".join(matched)))
        state["suggested"][a.scope] = {k: v for k, v in log.items() if v >= cutoff}
        save_json(STATE, state)
    if down:
        print("(unavailable right now: %s)" % ", ".join(down))


if __name__ == "__main__":
    main()
```
